import { Box, BoxProps, HStack, Text } from '@chakra-ui/react'
import { PoolType } from '../pools/createPool/SelectPoolType'

const tagStyleMap: Record<PoolType, { title: string; tagStyle: BoxProps }> = {
  dlmm: {
    title: 'DLMM',
    tagStyle: {
      bg: 'primary_green_opacity.10',
      color: 'primary_green',
      borderColor: 'primary_green_opacity.20'
    }
  },
  clmm: {
    title: 'CLMM',
    tagStyle: {
      bg: 'primary_opacity.10',
      color: 'primary',
      borderColor: 'primary_opacity.20'
    }
  }
}

function PoolTag({
  poolType,
  type,
  displayFee,
  onMouseEnter,
  onMouseLeave
}: {
  poolType: PoolType
  type: 'position' | 'stats'
  displayFee: string
  onMouseEnter?: () => void
  onMouseLeave?: () => void
}) {
  const { title, tagStyle } = tagStyleMap[poolType]
  return (
    <HStack bg="bg_secondary" borderRadius="10px" border="1px solid" borderColor="border" gap="0" w="102px" p="1px" h="20px">
      <Text fontWeight="500" fontSize="12px" color={tagStyle?.color} flex="1">
        {title}
      </Text>
      <Box
        fontSize="12px"
        lineHeight="16px"
        h="16px"
        fontWeight="500"
        borderRadius="8px"
        border="none"
        flex="1"
        textAlign="center"
        {...tagStyle}
        onMouseEnter={onMouseEnter}
        onMouseLeave={onMouseLeave}
        cursor="pointer"
      >
        {displayFee}
      </Box>
    </HStack>
  )
}

export default PoolTag
